export function email(first: string, last: string, company: string, rng: Rng): string {
  const clean = (s: string) => s.normalize("NFD").replace(/[^a-zA-Z]/g, "").toLowerCase();
  return `${clean(first)}${rng.bool(0.3) ? "." + clean(last).charAt(0) : ""}@${clean(company)}.${rng.pick(pools.tlds)}`;
}

export function phone(rng: Rng): string {
  return `+1 ${rng.int(200, 989)} ${rng.int(200, 999)} ${String(rng.int(0, 9999)).padStart(4, "0")}`;
}

export function url(company: string, rng: Rng): string {
  return `https://${company.normalize("NFD").replace(/[^a-zA-Z]/g, "").toLowerCase()}.${rng.pick(pools.tlds)}`;
}
